<?php require_once __DIR__.'/config/config.php'; require_once __DIR__.'/config/auth.php'; require_login(); $page_title='Dashboard'; $total=(int)$pdo->query('SELECT COUNT(*) FROM dokumen')->fetchColumn(); $lengkap=(int)$pdo->query("SELECT COUNT(*) FROM dokumen WHERE status='lengkap'")->fetchColumn(); $review=(int)$pdo->query("SELECT COUNT(*) FROM dokumen WHERE status='perlu_review'")->fetchColumn(); $belum=(int)$pdo->query("SELECT COUNT(*) FROM dokumen WHERE status='belum_lengkap'")->fetchColumn(); $eps=$pdo->query('SELECT ep.kode, ep.judul, COUNT(de.dokumen_id) jumlah FROM elemen_penilaian ep LEFT JOIN dokumen_ep de ON de.ep_id=ep.id GROUP BY ep.id ORDER BY ep.urutan')->fetchAll(); require __DIR__.'/partials/header.php'; ?><div class="d-flex justify-content-between align-items-center mb-4"><div><h2>Dashboard MRMIK IT</h2><div class="text-muted">Kelengkapan dokumen dan bukti implementasi</div></div><span class="badge text-bg-light"><?=htmlspecialchars($_SESSION['user']['nama'])?></span></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="card stat shadow-sm"><div class="card-body"><div class="text-muted">Total Dokumen</div><div class="display-6 fw-bold"><?=$total?></div></div></div></div><div class="col-md-3"><div class="card stat shadow-sm"><div class="card-body"><div class="text-muted">Lengkap</div><div class="display-6 fw-bold text-success"><?=$lengkap?></div></div></div></div><div class="col-md-3"><div class="card stat shadow-sm"><div class="card-body"><div class="text-muted">Perlu Review</div><div class="display-6 fw-bold text-warning"><?=$review?></div></div></div></div><div class="col-md-3"><div class="card stat shadow-sm"><div class="card-body"><div class="text-muted">Belum Lengkap</div><div class="display-6 fw-bold text-danger"><?=$belum?></div></div></div></div></div><div class="card shadow-sm border-0"><div class="card-body"><h5 class="mb-3">Elemen Penilaian</h5><div class="table-responsive"><table class="table"><thead><tr><th>EP</th><th>Fokus</th><th>Dokumen Terkait</th><th>Aksi</th></tr></thead><tbody><?php foreach($eps as $ep):?><tr><td><strong><?=htmlspecialchars($ep['kode'])?></strong></td><td><?=htmlspecialchars($ep['judul'])?></td><td><?=$ep['jumlah']?></td><td><a class="btn btn-sm btn-outline-success" href="/MRMIKIT/mode-survei/detail.php?kode=<?=urlencode($ep['kode'])?>">Lihat Bukti</a></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require __DIR__.'/partials/footer.php';